def main():
    out = ROOT/'authored_B0_B21_v1.json'
    assert not out.exists()
    records = []
    active = None
    for line in TEXT.splitlines():
        if not line:
            continue
        if line.startswith('@'):
            active = line[1:]
            continue
        ident, meaning, english = line.split('|', 2)
        assert active in CONTEXTS
        records.append([ident, meaning, english])
    assert len(records) == 175
    save(out, dict(contexts=CONTEXTS, records=records,
        whole_clean_exchanges_read_before_drafting=True, current_English_not_consulted=True,
        source_name_item_title_andnative_consumer_bindings_pending=True, new_credit=0))


if __name__ == '__main__':
    main()
